import json,csv,hashlib,time
from pathlib import Path
R=Path(__file__).resolve().parent
def rows(p):return list(csv.DictReader(open(p)))
def dump(p,x):json.dump(x,open(p,'w'),indent=2,allow_nan=False);open(p,'a').write('\n')
def main():
 ts=json.load(open(R/'branches/B_basicLoss_noP_500/training_status.json'))
 # Keep a compact, directly readable row for every committed optimizer update.
 logp=R/'branches/B_basicLoss_noP_500/training_log.jsonl'
 if logp.exists():
  compact=[]
  for line in logp.read_text().splitlines():
   x=json.loads(line);ls=x['losses'];gn=x['gradient_norms'];pd=x['parameter_delta_norms']
   compact.append({'step':x['step'],'domain':x['domain'],'video':x['video'],'external_qp':x['external_qp'],'plan_row_sha256':x['plan_row_sha256'],'LPIPS':ls['LPIPS'],'rate_bpp':ls['rate_bpp'],'beta_rate':ls['beta_rate'],'proxy_L1':ls['proxy_L1'],'reconstruction_L1':ls['reconstruction_L1'],'weighted_reconstruction_L1':ls['weighted_reconstruction_L1'],'total_loss':ls['total_loss'],'DISTS':'inactive_not_computed','legacy_stat':'inactive_not_computed','FD':'inactive_not_computed','total_preclip_norm':gn['total_preclip'],'clip_coefficient':gn['clip_coefficient'],'bridge_grad_norm':gn['bridge'],'generator_grad_norm':gn['generator'],'bridge_parameter_delta_norm':pd['bridge'],'generator_parameter_delta_norm':pd['generator'],'lr_bridge':x['learning_rates']['bridge'],'lr_generator':x['learning_rates']['generator'],'step_seconds':x['elapsed_seconds'],'peak_memory_MiB':x['peak_memory_MiB']})
  with (R/'branches/B_basicLoss_noP_500/gradient_summary.csv').open('w',newline='') as f:
   w=csv.DictWriter(f,fieldnames=list(compact[0]) if compact else ['step']);w.writeheader();w.writerows(compact)
 es=json.load(open(R/'evaluation_status.json')) if (R/'evaluation_status.json').exists() else {'status':'NOT_STARTED','expected':39,'completed':0}
 if es.get('completed')==39:
  import aggregate36
  aggregate36.main()
  es=json.load(open(R/'evaluation_status.json'))
 training_ok=ts.get('status')=='PASS' and ts.get('committed_updates')==500 and ts.get('optimizer_internal_step')==500
 rows_rd=rows(R/'results/all_rd_points.csv') if (R/'results/all_rd_points.csv').exists() else []
 reuse=json.load(open(R/'audits/reuse_pointwise_verification.json'))
 plan=json.load(open(R/'audits/source_and_reuse.json'))
 counts={'O_original':sum(x['method']=='O_original' for x in rows_rd),'B_basicLoss_noP_500':sum(x['method']=='B_basicLoss_noP_500' for x in rows_rd),'F_fullLoss_noP_500':sum(x['method']=='F_fullLoss_noP_500' for x in rows_rd)}
 retry_records=[json.load(open(p)) for p in sorted((R/'tasks').glob('*.attempts.json'))]
 pooled=rows(R/'results/pooled_fid.csv') if (R/'results/pooled_fid.csv').exists() else []
 final={'status':'PASS' if training_ok and es.get('status')=='PASS' and len(rows_rd)==117 and len(pooled)==27 else 'INCOMPLETE','computation_status':'PASS' if training_ok and es.get('status')=='PASS' else 'INCOMPLETE','publication_status':'PENDING','checks':{'new_B_updates':ts.get('committed_updates',0),'B_optimizer_internal_step':ts.get('optimizer_internal_step'),'F_updates_new':0,'B_plan_sha256':plan['plan_sha256'],'B_plan_rows':plan['plan_prefix_rows'],'B_domain_counts':plan['domain_counts'],'initial_source_step0_sha256':plan['parent_step0']['sha256'],'F_checkpoint_sha256':plan['full_endpoint']['sha256'],'F_inference_sha256':plan['full_endpoint']['inference_sha256'],'verified_reused_O_F_points':reuse['points_verified'],'new_B_points':sum(x['method']=='B_basicLoss_noP_500' for x in rows_rd),'logical_RD_points':len(rows_rd),'expected_logical_RD_points':117,'pooled_FID_points':len(pooled),'expected_pooled_FID_points':27,'evaluation_retry_task_count':len(retry_records),'evaluation_failed_attempts':sum(int(x.get('attempts',0)) for x in retry_records),'evaluation_retry_records':retry_records,'all_full_points_64_frames_63_transitions_and_independent_decode':all(x['frames']=='64' and x['num_transitions']=='63' and str(x['real_RANS']).lower()=='true' and str(x['independent_decode_pass']).lower()=='true' and str(x['state_sync_pass']).lower()=='true' for x in rows_rd) if rows_rd else False,'all_bpp_formulas_verified':all(abs(float(x['actual_bpp'])-int(x['real_bytes'])*8/(64*1920*1080))<1e-15 for x in rows_rd) if rows_rd else False,'FID_closure_max_abs':max([abs(float(x['closure_error'])) for x in pooled],default=None),'same_QP_bitstream_equal_pairs':sum(str(x['bitstream_sha_equal']).lower()=='true' for x in rows(R/'results/same_qp_pairs.csv')) if (R/'results/same_qp_pairs.csv').exists() else None,'same_QP_pairs':len(rows(R/'results/same_qp_pairs.csv')) if (R/'results/same_qp_pairs.csv').exists() else 0,'method_point_counts':counts,'new_disabled_losses_not_computed':True,'one_new_B_branch_only':True},'known_scope':'nested basic objective vs existing full-loss package; DISTS + legacy spatial statistic + native FD are bundled; this is not an official training objective reproduction','completed_unix':time.time()}
 dump(R/'final_integrity.json',final)
 if training_ok and es.get('status')=='PASS' and len(rows_rd)==117:
  sumrows=rows(R/'results/equal_rate_summary.csv');fid=rows(R/'results/pooled_fid.csv');direct=rows(R/'results/same_qp_pairs.csv')
  lines=['# v6.36 results report','',f'Execution status: **{final["status"]}**. New training: **500/500** B updates. Original and F were read-only reused.','', '## Fixed scope','', 'Three methods: O_original, B_basicLoss_noP_500, F_fullLoss_noP_500. The new target is the explicit nested basic objective. F reuses v6.35 N_oursLoss_noP_500 at cumulative step 500. This report does not call the basic target an official objective. The F−B comparison is the combined DISTS + legacy spatial statistic + native-resolution FD package; individual terms are not separated.','', '## Point coverage','', f'RD points: {len(rows_rd)}/117 (78 verified historical O/F rows; 39 new B encodes). Pooled FID points: {len(fid)}/27. The fixed data sets are U-Long (6 videos), UVG holdout (2), HEVC-B (5), at QP 0/5/9. All rates are measured from full RANS streams.','', '## Per-video common-rate comparison','', 'Each video uses its own O/B/F measured-bpp intersection, 20 linear points in ln(actual bpp), no extrapolation, then video-equal weighting. Relative changes are metric changes, not bitrate savings.','', '|Dataset|Method|Reference|Metric|Method mean|Reference mean|Delta|Relative %|Videos|','|---|---|---|---|---:|---:|---:|---:|---:|']
  for x in sumrows:lines.append(f"|{x['dataset']}|{x['method']}|{x['reference']}|{x['metric']}|{float(x['method_mean']):.6g}|{float(x['reference_mean']):.6g}|{float(x['delta']):+.6g}|{float(x['relative_change_percent']):+.3f}|{x['video_count']}|")
  lines+=['','## Pooled FID anchors','','FID is pooled across dataset frames; per-video FID is not averaged. The values below are measured QP anchors.']
  lines+=['','|Dataset|Method|QP|FID|D_mu|D_cov|Mean actual bpp|Samples|','|---|---|---:|---:|---:|---:|---:|---:|']
  for x in fid:lines.append(f"|{x['dataset']}|{x['method']}|{x['QP']}|{float(x['FID']):.6g}|{float(x['D_mu']):.6g}|{float(x['D_cov']):.6g}|{float(x['mean_actual_bpp']):.7g}|{x['samples']}|")
  lines+=['','## Direct measured QP comparisons','','The full per-video table is `results/same_qp_pairs.csv`; QP matches are not treated as rate matches. Bitstream equality is independently listed for each pair.','',f"Bitstream hash equality among the {len(direct)} same-QP method pairs: {sum(str(x['bitstream_sha_equal']).lower()=='true' for x in direct)}/{len(direct)}.",'',f"Evaluation retries: {len(retry_records)} task(s), {sum(int(x.get('attempts',0)) for x in retry_records)} failed attempt(s); original failures and tracebacks are preserved in task logs.",'','## Artifacts','', '- `results/all_rd_points.csv`: 117 measured/reused point records.','- `results/pooled_fid.csv`: 27 pooled FID points with D_mu/D_cov.','- `results/equal_rate_summary.csv`: per-video common-rate interpolation summary.','- `results/equal_rate_per_video.csv`, `results/equal_rate_bands.csv`, `results/global_common_rate_summary.csv`.','- `audits/reuse_pointwise_verification.json`: historical artifact hash checks.','- `final_integrity.json`: calculation status.','', 'The screen uses one training seed and a fixed 500-update budget. It does not establish convergence.']
  (R/'REPORT.md').write_text('\n'.join(lines)+'\n')
  (R/'RESULTS_SUMMARY.md').write_text(f"""# Results summary\n\n- New B training updates: 500/500.\n- F and O updates in this run: 0; 78 evaluation points reused after artifact verification.\n- New B real encodes: 39/39.\n- Logical RD points: 117/117.\n- Dataset-pooled FID points: 27/27.\n- Final calculation integrity: {final['status']}.\n- Objective: explicit no-P nested basic target compared with an existing no-P full-loss endpoint. The full-loss extras are a bundled supervision package.\n\nSee [REPORT.md](REPORT.md), `results/`, and `audits/` for numeric tables and provenance.\n""")
  dump(R/'pipeline_status.json',{'status':'CALCULATION_COMPLETE','training':{'status':'PASS','committed_updates':500},'evaluation':{'status':'PASS','completed':39,'expected':39},'aggregation':{'status':'PASS','RD_points':117,'pooled_FID_points':27},'publication':{'status':'PENDING'},'updated_unix':time.time()})
 print(final['status'],final['checks'])
if __name__=='__main__':main()
